// Shared documentation for the public website, integration panel and admin documentation.
$waDocPublic=(bool)($waDocPublic??false);
if(empty($waDocRoot)){
    $waSite='';try{$waQuery=appDb()->prepare("SELECT setting_value FROM system_settings WHERE setting_key='seo_site_url' LIMIT 1");$waQuery->execute();$waSite=trim((string)$waQuery->fetchColumn());}catch(Throwable $waError){}
    if($waSite==='')$waSite=trim((string)(envConfig($root.'/.env')['APP_URL']??''));
    if($waSite==='')$waSite=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost');
    $waDocRoot=rtrim($waSite,'/').'/api.php?r=';
