$waDocVersion='2.31.146';try{$waVersionQuery=appDb()->prepare("SELECT setting_value FROM system_settings WHERE setting_key='app_version' LIMIT 1");$waVersionQuery->execute();$waVersionFound=(string)$waVersionQuery->fetchColumn();if(preg_match('/^\d+\.\d+\.\d+$/',$waVersionFound)&&version_compare($waVersionFound,$waDocVersion,'>'))$waDocVersion=$waVersionFound;}catch(Throwable $waVersionError){}
$waEscape=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$waExample=static function(array $payload,string $requestId)use($waDocRoot):string{
    return 'curl -X POST '.escapeshellarg($waDocRoot.'v1/whatsapp/send')." -H 'Authorization: Bearer TU_CLAVE_API' -H 'Content-Type: application/json' -H 'Idempotency-Key: ".$requestId."' -d ".escapeshellarg(json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));
};
$waExamples=[
 ['individual','Envío individual','whatsapp:send','Un mensaje a un número internacional.',$waExample(['channel_id'=>12,'to'=>'50499990000','message'=>'Su factura está disponible.'],'factura-123-individual')],
 ['bulk','Envío masivo','whatsapp:bulk','Entre 2 y 100 destinatarios con autorización; los números repetidos se consolidan.',$waExample(['channel_id'=>12,'to'=>['50499990000','50499990001'],'message'=>'Nueva notificación de servicio.','consent_confirmed'=>true],'aviso-123-lote-01')],
 ['url','Documento por URL','whatsapp:send','URL HTTPS pública, accesible por Meta durante el envío. Para QR use Base64.',$waExample(['channel_id'=>12,'to'=>'50499990000','message'=>'Adjuntamos su factura.','attachments'=>[['name'=>'Factura.pdf','mime'=>'application/pdf','url'=>'https://ejemplo.com/factura.pdf']]],'factura-123-url')],
 ['base64','Adjunto Base64','whatsapp:send','Compatible con Cloud API y QR. Sustituya el marcador por los bytes del archivo codificados en Base64.',$waExample(['channel_id'=>12,'to'=>'50499990000','attachments'=>[['name'=>'Factura.pdf','data_base64'=>'BASE64_DEL_ARCHIVO']]],'factura-123-base64')],
 ['template','Plantilla de Meta','whatsapp:send','Use el ID numérico de una plantilla aprobada y sus valores en el orden definido.',$waExample(['channel_id'=>12,'to'=>'50499990000','template_id'=>'123456789','template_values'=>['Cliente','F-001']],'factura-123-template')],
 ['status','Consultar estado','whatsapp:status','Consulte cada UUID devuelto por el envío, incluso si forma parte de un lote.','curl -G '.escapeshellarg($waDocRoot.'v1/whatsapp/status')." -H 'Authorization: Bearer TU_CLAVE_API' --data-urlencode 'message_uuid=123e4567-e89b-12d3-a456-426614174000'"],
];
